  "implementation": "import math

def solve(case):
    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'lengths' not in case or 'scores' not in case or 'budget' not in case:
        raise ValueError("case missing required fields")
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    if not isinstance(lengths, list) or not isinstance(scores, list):
        raise ValueError("lengths and scores must be lists")
    if len(lengths) != len(scores):
        raise ValueError("lengths and scores must have same length")
    if not isinstance(budget, int) or budget < 0:
        raise ValueError("budget must be a non-negative integer")
    n = len(lengths)
    # DP array: dp[w] = (score, weight_used, indices_tuple) or None
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, ())

    # Comparison helper with tolerance
    EPS = 1e-12

    def better(score1, weight1, ind1, score2, weight2, ind2):
        # returns True if (score1,weight1,ind1) is better than (score2,weight2,ind2)
        if not math.isclose(score1, score2, rel_tol=EPS, abs_tol=EPS):
            return score1 > score2
        if weight1 != weight2:
            return weight1 < weight2
        # lexicographic compare tuples (already sorted)
        return ind1 < ind2

    for i in range(n):
        w = lengths[i]
        s = scores[i]
        for cap in range(budget, w - 1, -1):
            prev = dp[cap - w]
            if prev is not None:
                new_score = prev[0] + s
                new_weight = prev[1] + w
                new_indices = prev[2] + (i,)
                cur = dp[cap]
                if cur is None or better(new_score, new_weight, new_indices, cur[0], cur[1], cur[2]):
                    dp[cap] = (new_score, new_weight, new_indices)

    # Find best overall solution among all capacities
    best = None
    best_cap = None
    for cap in range(budget + 1):
        cur = dp[cap]
        if cur is not None:
            if best is None or better(cur[0], cur[1], cur[2], best[0], best[1], best[2]):
                best = cur
                best_cap = cap

    if best is None:
        # This should not happen because dp[0] always exists
        return {"selected_indices": [], "tokens_used": 0, "total_score": 0.0}

    selected_indices = list(best[2])
    tokens_used = best[1]
    total_score = best[0]

    return {
        "selected_indices": selected_indices,
        "tokens_used": tokens_used,
        "total_score": total_score
    }
